diff --git a/core/worldline-c_api.adb b/core/worldline-c_api.adb
index 74bf871..15f9c21 100644
--- a/core/worldline-c_api.adb
+++ b/core/worldline-c_api.adb
@@ -2738,6 +2738,14 @@ package body Worldline.C_API with SPARK_Mode => Off is
             Write_Result (Result, (Status => L.Result_Status'Pos (Status), Total => Encode (Total)));
          end if;
          return Transport;
+      exception
+         when others =>
+            -- Preserve the original typed adapter cleanup at the foreign
+            -- exception boundary. No output is exported on transport failure.
+            Detail_Arena := (others => 0); Total_Arena := (others => 0);
+            Typed_Details := (others => L.Empty); Total := L.Empty;
+            Status := L.Invalid_Input;
+            raise;
       end;
    exception
       when others =>
@@ -2795,6 +2803,11 @@ package body Worldline.C_API with SPARK_Mode => Off is
             Write_Result (Result, (Status => L.Result_Status'Pos (Status), Total => Encode (Typed_Result)));
          end if;
          return Transport;
+      exception
+         when others =>
+            Output_Arena := (others => 0); Typed_Result := L.Empty;
+            Status := L.Invalid_Input;
+            raise;
       end;
    exception
       when others =>
diff --git a/core/worldline-resource_ledger_c_api.adb b/core/worldline-resource_ledger_c_api.adb
index 78aeeef..1788fe6 100644
--- a/core/worldline-resource_ledger_c_api.adb
+++ b/core/worldline-resource_ledger_c_api.adb
@@ -156,9 +156,6 @@ package body Worldline.Resource_Ledger_C_API with SPARK_Mode => On is
                     Typed_Details, Total, Status);
          return 0;
       end;
-   exception
-      when others => Detail_Arena := (others => 0); Total_Arena := (others => 0);
-         Typed_Details := (others => L.Empty); Total := L.Empty; Status := L.Invalid_Input; return 255;
    end Compute;
    function Headroom
      (Data : not null access constant Resource_Quantities.Byte_Array;
@@ -188,7 +185,5 @@ package body Worldline.Resource_Ledger_C_API with SPARK_Mode => On is
             return 0;
          end;
       end;
-   exception
-      when others => Output_Arena := (others => 0); Typed_Result := L.Empty; Status := L.Invalid_Input; return 255;
    end Headroom;
 end Worldline.Resource_Ledger_C_API;
diff --git a/core/worldline-resource_ledger_c_api.ads b/core/worldline-resource_ledger_c_api.ads
index e88c065..87e0304 100644
--- a/core/worldline-resource_ledger_c_api.ads
+++ b/core/worldline-resource_ledger_c_api.ads
@@ -2,6 +2,9 @@
 --  The unchanged C exports are enrolled in the existing sole Off Worldline.C_API.
 --  C_API maps constrained views only after numeric transport validation; the
 --  original loops below take the single snapshot before any foreign output write.
+--  Runtime exception containment and discarded-output cleanup belong to that
+--  existing foreign boundary. Typed callers must not consume outputs if a call
+--  raises; the boundary converts the failure to transport 255 before export.
 with Resource_Quantities;
 with Resource_Ledger;
 with Interfaces;
